-- Monday 16 Nov 2026: the Zumba Toning SPECIAL at 17:00 doesn't take place – the studio took it off the schedule, only
-- the Zumba fitness SPECIAL at 18:00 stays (with the guests from Olomouc). Everything on the web that still invites to
-- the Toning or sells both lessons together is put right. Each step only where the fitness SPECIAL is in the schedule and
-- the Toning isn't, and only while the text is still the one that mentions it – what the studio has rewritten stays.
-- (The bundle itself needs nothing: with one lesson left it isn't offered any more, a paid one keeps its record.)
--
-- The lesson's note: no „both for 300 Kč“.
UPDATE "class_sessions" SET "note" = replace("note", ' Jdeš na obě? Balíček Toning + fitness vyjde na 300 Kč (kartou nebo převodem).', '')
WHERE "id" = '00d2c63c-54d6-4248-a5a0-842b458b2e96' AND "note" LIKE '%Balíček Toning + fitness%'
  AND EXISTS (SELECT 1 FROM "class_sessions" f WHERE f."id" = '00d2c63c-54d6-4248-a5a0-842b458b2e96' AND f."status"::text = 'scheduled')
  AND NOT EXISTS (SELECT 1 FROM "class_sessions" t WHERE t."id" = '5ea2983c-b146-45ae-b4b6-f86c43acc4c4' AND t."status"::text = 'scheduled');
--> statement-breakpoint
-- The board post, in the studio's own words: one lesson, its price, one link – and a line about the change.
UPDATE "announcements" SET "body" = $body$<p>16. listopadu chystáme fitness odpoledne s mými milovanými kolegy z Olomouce! Přijedou za námi lektoři <strong>Marek a Martin</strong> – a samozřejmě nebude chybět ani jáááá. 💛</p><ul><li><p>🕕 <strong>18:00–19:00 Zumba fitness SPECIAL</strong> – hodina latinskoamerických rytmů a čisté radosti z pohybu</p></li></ul><p><strong>Změna programu:</strong> Zumba Toning v 17:00 se nakonec nekoná – omlouváme se. O to víc to společně rozjedeme v 18:00! 💃</p><p>Žádné zkušenosti nepotřebuješ – stačí chuť se hýbat a dobrá nálada. 🎉</p><h2><strong>Kolik to stojí?</strong></h2><p>členové nic neplatí – lekci mají v ceně členství!</p><ul><li><p>s permanentkou se strhne 1 vstup</p></li><li><p>jednorázově 250 Kč či 220 kreditů</p></li></ul><p>Přihlašování je otevřené pro všechny už teď. 👉 Rezervuj si místo: <a href="/rozvrh/00d2c63c-54d6-4248-a5a0-842b458b2e96">18:00 Zumba fitness SPECIAL</a></p><p>Těšíme se na vás! 💃🕺</p><p>Terka a M&amp;M team :)</p>$body$
WHERE "id" = '146aa9e2-80ab-437c-b082-47ecb7403616' AND "body" LIKE '%/rozvrh/5ea2983c-b146-45ae-b4b6-f86c43acc4c4%'
  AND EXISTS (SELECT 1 FROM "class_sessions" f WHERE f."id" = '00d2c63c-54d6-4248-a5a0-842b458b2e96' AND f."status"::text = 'scheduled')
  AND NOT EXISTS (SELECT 1 FROM "class_sessions" t WHERE t."id" = '5ea2983c-b146-45ae-b4b6-f86c43acc4c4' AND t."status"::text = 'scheduled');
--> statement-breakpoint
-- The bar at the top of the web (the studio's wording, without the Toning).
UPDATE "content" SET "value" = '💃 Pondělí 16. 11. v 18:00 – Zumba SPECIAL s Márou, Marťou a Terkou!', "updated_at" = now()
WHERE "key" = 'promoBar.text' AND "value" LIKE '%Toning%'
  AND EXISTS (SELECT 1 FROM "class_sessions" f WHERE f."id" = '00d2c63c-54d6-4248-a5a0-842b458b2e96' AND f."status"::text = 'scheduled')
  AND NOT EXISTS (SELECT 1 FROM "class_sessions" t WHERE t."id" = '5ea2983c-b146-45ae-b4b6-f86c43acc4c4' AND t."status"::text = 'scheduled');
