-- …and of the two lessons' buttons one stays, to the Zumba at 18:00.
UPDATE "content" SET "value" = CASE "key"
    WHEN 'popup.buttonLabel' THEN 'Rezervovat Zumbu 18:00'
    WHEN 'popup.buttonUrl' THEN '/rozvrh/00d2c63c-54d6-4248-a5a0-842b458b2e96'
    ELSE '' END, "updated_at" = now()
WHERE "key" IN ('popup.buttonLabel', 'popup.buttonUrl', 'popup.buttonLabel2', 'popup.buttonUrl2')
  AND EXISTS (SELECT 1 FROM "content" c WHERE c."key" = 'popup.buttonUrl' AND c."value" LIKE '%5ea2983c-b146-45ae-b4b6-f86c43acc4c4%')
  AND EXISTS (SELECT 1 FROM "class_sessions" f WHERE f."id" = '00d2c63c-54d6-4248-a5a0-842b458b2e96' AND f."status"::text = 'scheduled')
